# Helper to add questions
def append_questions(q_list, category_id):
    existing_ids = {q['id'] for q in data['questions']}
    added = 0
    for q_id, q_text, ans, hint, diff in q_list:
        if q_id not in existing_ids:
            data['questions'].append({
                "id": q_id,
                "categoryId": category_id,
                "question": q_text,
                "answer": ans,
                "hint": hint,
                "difficulty": diff
            })
            existing_ids.add(q_id)
            added += 1
    return added

