c6 = append_questions(reversed_words_new, 'reversed_words')
c7 = append_questions(emoji_movies_new, 'emoji_movies')
c8 = append_questions(challenges_new, 'challenges')
c9 = append_questions(desc_new, 'description_guess')
c10 = append_questions(history_new, 'history')
c11 = append_questions(geo_new, 'geography')

